// Generated by scripts (football-logos). Real club crests, matched by name.
// Source: https://github.com/luukhopman/football-logos (crests are club
// trademarks; used here for a local, non-commercial analyst dashboard).

export function normTeam(name: string): string {
  return name
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    // Drop a trailing country/qualifier code, e.g. "Arsenal FC (ENG)".
    .replace(/\s*\([a-z]{2,4}\)\s*$/, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

